function createCounter(n: number): () => number {
  return () => n++;
}

function countFrom(n: number, calls: number): number[] {
  const counter = createCounter(n);
  const out: number[] = [];
  for (let i = 0; i < calls; i++) out.push(counter());
  return out;
}

