class Solution:
    def createCounter(self, n: int):
        def counter():
            nonlocal n
            n += 1
            return n - 1
        return counter

    def countFrom(self, n: int, calls: int) -> List[int]:
        counter = self.createCounter(n)
        return [counter() for _ in range(calls)]

