function* createCounter(n: number): Generator<number> {
  while (true) yield n++;
}

function countFrom(n: number, calls: number): number[] {
  const counter = createCounter(n);
  const out: number[] = [];
  for (let i = 0; i < calls; i++) out.push(counter.next().value);
  return out;
}

